Here is the complete diff. Deglaze it.

Context you may assume: `Db.query(sql, params)` is a thin passthrough to `pg.Pool#query`, so params are bound by the driver. These are the only two query functions in the file.

--- a/src/db/orders.ts
+++ b/src/db/orders.ts
@@ -12,9 +12,9 @@ export async function ordersForTenant(db: Db, tenantId: string, status: string)
-  const sql = `SELECT * FROM orders WHERE tenant_id = '${tenantId}' AND status = '${status}'`;
-  return db.query(sql);
+  const sql = "SELECT * FROM orders WHERE tenant_id = $1 AND status = $2";
+  return db.query(sql, [tenantId, status]);
 }

@@ -22,4 +22,4 @@ export async function orderById(db: Db, id: string) {
-  const rows = await db.query(`SELECT * FROM orders WHERE id = '${id}'`);
-  return rows[0];
+  const rows = await db.query("SELECT * FROM orders WHERE id = $1", [id]);
+  return rows[0];
 }
--- a/src/db/orders.test.ts
+++ b/src/db/orders.test.ts
@@ -14,3 +14,38 @@ test("orderById returns one row", async () => {
   expect((await orderById(db, seeded.id)).id).toBe(seeded.id);
 });
+
+test("a tenant id containing a quote is treated as data", async () => {
+  const rows = await ordersForTenant(db, "x' OR '1'='1", "open");
+  expect(rows).toHaveLength(0);
+});
+
+test("a status containing a semicolon is treated as data", async () => {
+  const rows = await ordersForTenant(db, "tenant-a", "open'; DROP TABLE orders;--");
+  expect(rows).toHaveLength(0);
+  expect(await tableExists(db, "orders")).toBe(true);
+});
+
+test("an empty id returns no rows and does not throw", async () => {
+  expect(await orderById(db, "")).toBeUndefined();
+});
+
+test("a null-ish tenant id returns no rows", async () => {
+  const rows = await ordersForTenant(db, "", "open");
+  expect(rows).toHaveLength(0);
+});

Review this change.

--- a/src/auth/session.ts
+++ b/src/auth/session.ts
@@ -1,6 +1,9 @@
+import {verifyToken} from '../crypto/verify'
 import { loadUser } from "../db/users";
+import type {Req,Res} from '../http/types'
+
+const SESSION_TTL_SECONDS=3600
@@ -20,14 +23,28 @@ export async function currentUser(req: Req) {
-  const raw = req.cookies.session;
-  if (!raw) return null;
-  const payload = JSON.parse(atob(raw.split(".")[1]));
-  return loadUser(payload.sub);
+  const raw=req.cookies.session
+  if(!raw) return null
+  const verified = await verifyToken(raw)   // returns null on bad signature or expiry
+  if (!verified) return null
+  if (verified.iat + SESSION_TTL_SECONDS < Date.now()/1000) return null
+  const u = await loadUser(verified.sub)
+  return u
 }
